   168→
   169→function buildOpenTabFlag(options?: DesktopNavigationOptions): boolean {
   170→  return options?.openMode === "new-tab";
   171→}
   172→
   173→function safeHostname(url: string): string {
   174→  try {
   175→    return new URL(url).hostname;
   176→  } catch {
   177→    return url;
   178→  }
   179→}
   180→
   181→function inferWorkspaceId(location: DesktopLocation | null): string | null {
   182→  if (!location) {
   183→    return null;
   184→  }
   185→
   186→  return "workspaceId" in location ? location.workspaceId : null;
   187→}
   188→
   189→function pathToDesktopLocation(path: string): DesktopLocation {
   190→  return urlToLocation(path) ?? { kind: "global-route", path };
   191→}
   192→
   193→export function useDesktopRouting(): DesktopRoutingApi {
   194→  const { t } = useTranslation();
   195→  const tabState = useActiveTabState();
   196→  const tabActions = useTabActions();
   197→  const tabNav = useTabNavigation();
   198→  const shell = useOptionalNavigationShell();
   199→  const shellHeader = useNavigationShellHeaderState();
   200→  const ownerId = useId();
   201→
   202→  const currentRoute = tabState.currentNavigationState?.location ?? null;
   203→  const currentNavigationStack = tabState.currentNavigationState?.breadcrumbStack;
   204→  const currentStack = useMemo(
   205→    () => currentNavigationStack ?? [],
   206→    [currentNavigationStack]
   207→  );
   208→  const currentDescriptor = currentStack[currentStack.length - 1] ?? null;
   209→  const currentWorkspaceId = inferWorkspaceId(currentRoute);
   210→  const currentWorkspace = shellHeader?.workspace;
   211→
   212→  const openRoute = useCallback(
   213→    (route: DesktopLocation, options?: DesktopNavigationOptions) => {
   214→      tabActions.openLocation(route, {
   215→        openInNewTab: buildOpenTabFlag(options),
   216→      });
   217→    },
   218→    [tabActions]
   219→  );
   220→
   221→  const focusOrOpenRoute = useCallback(
   222→    (route: DesktopLocation) => {
   223→      tabActions.openLocation(route);
   224→    },
   225→    [tabActions]
   226→  );
   227→
   228→  const openPath = useCallback(
   229→    (
   230→      path: string,
   231→      input?: {
   232→        title?: string;
   233→        icon?: IconData;
   234→        workspaceId?: string;
   235→        slug?: string;
   236→        descriptorId?: string;
   237→        openMode?: DesktopNavigationOptions["openMode"];
   238→      }
   239→    ) => {
   240→      if (input?.openMode === "new-tab") {
   241→        const location = pathToDesktopLocation(path);
   242→        tabActions.openLocation(location, { openInNewTab: true });
   243→        return;
   244→      }
   245→
   246→      tabActions.navigateTo(path, {
   247→        label: input?.title ?? path,
   248→        icon: input?.icon,
   249→        descriptorId: input?.descriptorId,
   250→        meta: { workspaceId: input?.workspaceId },
   251→      });
   252→    },
   253→    [tabActions]
   254→  );
   255→
   256→  const openWorkspaceHome = useCallback(
   257→    (workspaceId: string, options?: DesktopNavigationOptions) => {
   258→      tabActions.openLocation(
   259→        { kind: "workspace-home", workspaceId },
   260→        {
   261→          openInNewTab: buildOpenTabFlag(options),
   262→        }
   263→      );
   264→    },
   265→    [tabActions]
   266→  );
   267→
   268→  const openWorkspaceApps = useCallback(
   269→    (workspaceId: string, options?: DesktopNavigationOptions) => {
   270→      tabActions.openLocation(
   271→        { kind: "workspace-apps", workspaceId },
   272→        {
   273→          openInNewTab: buildOpenTabFlag(options),
   274→        }
   275→      );
   276→    },
   277→    [tabActions]
   278→  );
   279→
   280→  const pushChildPage = useCallback(
   281→    (
   282→      item: BreadcrumbStackItem,
   283→      location: DesktopLocation,
   284→      options?: {
   285→        mode?: "push" | "replace";
   286→        openMode?: DesktopNavigationOptions["openMode"];
   287→      }
   288→    ) => {
   289→      if (options?.openMode === "new-tab") {
   290→        tabActions.openLocation(location, {
   291→          openInNewTab: true,
   292→          breadcrumbStack: [...currentStack, item],
   293→        });
   294→        return;
   295→      }
   296→
   297→      tabActions.pushPage(item, location, {
   298→        mode: options?.mode,
   299→      });
   300→    },
   301→    [currentStack, tabActions]
   302→  );
   303→
   304→  const openWorkspaceSection = useCallback(
   305→    (
   306→      workspaceId: string,
   307→      section: WorkspaceSection,
   308→      options?: DesktopNavigationOptions
   309→    ) => {
   310→      const location: DesktopLocation = { kind: "workspace-section", workspaceId, section };
   311→
   312→      if (options?.stackMode === "push") {
   313→        const descriptor = getWorkspaceSectionDescriptor(section);
   314→        pushChildPage(
   315→          createLocationBreadcrumbItem(location, {
   316→            id: `${workspaceId}:${section}`,
   317→            descriptorId: `workspace-section:${section}`,
   318→            label: descriptor
   319→              ? t(descriptor.titleKey, descriptor.fallbackLabel)
   320→              : section,
   321→            icon: descriptor?.icon,
   322→            meta: { workspaceId, section },
   323→          }),
   324→          location,
   325→          { mode: "push" }
   326→        );
   327→        return;
   328→      }
   329→
   330→      tabActions.openLocation(location, {
   331→        openInNewTab: buildOpenTabFlag(options),
   332→      });
   333→    },
   334→    [tabActions, pushChildPage, t]
   335→  );
   336→
   337→  const openWorkspaceAgentList = useCallback(
   338→    (workspaceId: string, options?: DesktopNavigationOptions) => {
   339→      openWorkspaceSection(workspaceId, "agent", options);
   340→    },
   341→    [openWorkspaceSection]
   342→  );
   343→
   344→  const openChildLocation = useCallback(
   345→    (
   346→      location: DesktopLocation,
   347→      item: BreadcrumbStackItem,
   348→      options?: DesktopNavigationOptions
   349→    ) => {
   350→      const explicitStack = options?.breadcrumbStack;
   351→
   352→      if (options?.openMode === "new-tab") {
   353→        tabActions.openLocation(location, {
   354→          openInNewTab: true,
   355→          breadcrumbStack: explicitStack ?? [...currentStack, item],
   356→        });
   357→        return;
   358→      }
   359→
   360→      if (explicitStack) {
   361→        const openStackMode = options?.stackMode ?? "push";
   362→        const navigateWithExplicitStack =
   363→          openStackMode === "push" ? tabActions.pushLocation : tabActions.openLocation;
   364→
   365→        navigateWithExplicitStack(location, {
   366→          breadcrumbStack: explicitStack,
   367→        });
   368→        return;
   369→      }
   370→
   371→      const sameWorkspace =
   372→        !("workspaceId" in location) ||
   373→        !currentWorkspaceId ||
   374→        currentWorkspaceId === location.workspaceId;
   375→      const stackMode =
   376→        options?.stackMode ?? (currentStack.length > 0 && sameWorkspace ? "push" : "open");
   377→
   378→      if (stackMode === "open") {
   379→        tabActions.openLocation(location);
   380→        return;
   381→      }
   382→
   383→      pushChildPage(item, location, {
   384→        mode: stackMode,
   385→      });
   386→    },
   387→    [currentStack, currentWorkspaceId, tabActions, pushChildPage]
   388→  );
   389→
   390→  const openWorkspaceAgentDetail = useCallback(
   391→    (
   392→      workspaceId: string,
   393→      agentId: string,
