   423→      options?: DesktopNavigationOptions
   424→    ) => {
   425→      const location: DesktopLocation = {
   426→        kind: "workspace-executor-detail",
   427→        workspaceId,
   428→        executorType,
   429→      };
   430→      openChildLocation(
   431→        location,
   432→        createLocationBreadcrumbItem(location, {
   433→          id: `workspace:${workspaceId}:executor:${executorType}`,
   434→          descriptorId: "workspace-executor",
   435→          label: options?.title ?? executorType,
   436→          icon: options?.icon ?? { type: "lucide", value: "terminal" },
   437→          meta: {
   438→            workspaceId,
   439→            executorType,
   440→          },
   441→        }),
   442→        options
   443→      );
   444→    },
   445→    [openChildLocation]
   446→  );
   447→
   448→  const openWorkspacePage = useCallback(
   449→    (
   450→      workspaceId: string,
   451→      pageSlug: string,
   452→      options?: DesktopNavigationOptions
   453→    ) => {
   454→      tabActions.openLocation(
   455→        { kind: "workspace-page", workspaceId, pageSlug },
   456→        {
   457→          openInNewTab: buildOpenTabFlag(options),
   458→          breadcrumbStack: options?.breadcrumbStack,
   459→        }
   460→      );
   461→    },
   462→    [tabActions]
   463→  );
   464→
   465→  const pushWorkspaceAgentDetail = useCallback(
   466→    (
   467→      workspaceId: string,
   468→      agentId: string,
   469→      options?: { title?: string; icon?: IconData; mode?: "push" | "replace"; openMode?: DesktopNavigationOptions["openMode"] }
   470→    ) =>
   471→      openWorkspaceAgentDetail(workspaceId, agentId, {
   472→        title: options?.title,
   473→        icon: options?.icon,
   474→        openMode: options?.openMode,
   475→        stackMode: options?.mode === "replace" ? "replace" : "push",
   476→      }),
   477→    [openWorkspaceAgentDetail]
   478→  );
   479→
   480→  const pushWorkspaceExecutorDetail = useCallback(
   481→    (
   482→      workspaceId: string,
   483→      executorType: string,
   484→      options?: { title?: string; icon?: IconData; mode?: "push" | "replace"; openMode?: DesktopNavigationOptions["openMode"] }
   485→    ) =>
   486→      openWorkspaceExecutorDetail(workspaceId, executorType, {
   487→        title: options?.title,
   488→        icon: options?.icon,
   489→        openMode: options?.openMode,
   490→        stackMode: options?.mode === "replace" ? "replace" : "push",
   491→      }),
   492→    [openWorkspaceExecutorDetail]
   493→  );
   494→
   495→  const openWorkspaceWeb = useCallback(
   496→    (
   497→      workspaceId: string,
   498→      input: { url: string; title?: string; webId?: string },
