   508→          webId: input.webId,
   509→        },
   510→        {
   511→          openInNewTab: buildOpenTabFlag(options),
   512→        }
   513→      );
   514→    },
   515→    [tabActions]
   516→  );
   517→
   518→  const openSettings = useCallback(
