   522→    ) => {
   523→      const normalizedSection = normalizeSettingsSection(section);
   524→      tabActions.openLocation(
   525→        { kind: "settings", section: normalizedSection },
   526→        {
   527→          openInNewTab: buildOpenTabFlag(options),
