   529→      );
   530→    },
   531→    [tabActions]
   532→  );
   533→
   534→  const openAgentDetail = useCallback(
   535→    (
   536→      agentId: string,
   537→      workspacePath?: string,
   538→      options?: DesktopNavigationOptions
   539→    ) => {
   540→      const location: DesktopLocation = { kind: "agent-detail", agentId, workspacePath };
   541→      openChildLocation(
   542→        location,
   543→        createLocationBreadcrumbItem(location, {
   544→          id: `agent:${agentId}`,
   545→          descriptorId: "workspace-agent",
   546→          label: options?.title ?? agentId,
