   613→    ) => {
   614→      const location: DesktopLocation = {
   615→        kind: "subagent-detail",
   616→        configId,
   617→        executorType: input.executorType,
   618→        workspacePath: input.workspacePath,
   619→      };
   620→      openChildLocation(
   621→        location,
   622→        createLocationBreadcrumbItem(location, {
   623→          id: `subagent:${configId}`,
   624→          descriptorId: "workspace-agent",
   625→          label: configId,
   626→          icon: { type: "lucide", value: "bot" },
   627→          meta: {
   628→            workspaceId: currentWorkspaceId ?? currentStack[0]?.meta?.workspaceId,
   629→            executorType: input.executorType,
