  1004→  routing: Pick<DesktopRoutingApi, "setHeaderCenter" | "setHeaderRight" | "clearHeaderSlots">,
  1005→  centerContent: ReactNode | null | undefined,
  1006→  rightContent: ReactNode | null | undefined
  1007→) {
