  1013→
  1014→  useEffect(() => {
  1015→    setHeaderRight(rightContent ?? null);
  1016→  }, [rightContent, setHeaderRight]);
  1017→
  1018→  useEffect(() => clearHeaderSlots, [clearHeaderSlots]);
  1019→}
