     2→import { registry } from "./route-registry";
     3→import { buildColdStartBreadcrumb, deriveAncestorsFromPrefix, buildBreadcrumbItem, type NavigateHeaders, type BreadcrumbStackItem } from "./breadcrumb-builder";
     4→import type { RouteMatch } from "./route-compiler";
     5→
     6→export type NavigateMethod = "push" | "replace" | "reset";
     7→
     8→/**
     9→ * Build the leaf BreadcrumbStackItem for a given URL.
    10→ * Used by the navigate function and can be used standalone.
    11→ */
    12→export function buildNavigateLeaf(url: string, headers?: NavigateHeaders): BreadcrumbStackItem {
    13→  const match = registry.match(url);
    14→  const fallbackLabel = url.split("/").filter(Boolean).pop() ?? url;
    15→
    16→  return {
    17→    id: headers?.id ?? url,
    18→    label: headers?.label ?? match?.title ?? fallbackLabel,
    19→    icon: headers?.icon ?? match?.icon,
    20→    pattern: match?.pattern,
    21→    href: url,
    22→    sourceNodeId: headers?.sourceNodeId,
    23→    parentNodeId: headers?.parentNodeId,
    24→    meta: headers?.meta,
    25→  };
    26→}
    27→
    28→/**
    29→ * Unified navigate function — the primary API for all navigation.
    30→ *
    31→ * Called from use-desktop-routing hooks. Dispatches to the appropriate
    32→ * tab store action based on method.
    33→ *
    34→ * @param method - "push" appends leaf to stack, "replace" replaces top, "reset" rebuilds from cold-start
    35→ * @param url - The target URL (built via registry.build)
    36→ * @param headers - Optional overrides for the breadcrumb leaf (label, icon, meta, etc.)
    37→ * @param tabStore - Tab store actions (injected by hook to avoid module-level coupling)
    38→ */
    39→export function navigate(
    40→  method: NavigateMethod,
    41→  url: string,
    42→  headers: NavigateHeaders | undefined,
    43→  tabStore: {
    44→    activeTabId: string;
    45→    pushNavigation: (tabId: string, url: string, leaf: BreadcrumbStackItem) => void;
    46→    replaceNavigation: (tabId: string, url: string, leaf: BreadcrumbStackItem) => void;
    47→    resetNavigation: (tabId: string, url: string, stack: BreadcrumbStackItem[]) => void;
    48→  },
    49→): void {
    50→  const { activeTabId } = tabStore;
    51→  const leaf = buildNavigateLeaf(url, headers);
    52→
    53→  switch (method) {
    54→    case "push":
    55→      tabStore.pushNavigation(activeTabId, url, leaf);
    56→      break;
    57→    case "replace":
    58→      tabStore.replaceNavigation(activeTabId, url, leaf);
    59→      break;
    60→    case "reset": {
    61→      const stack = buildColdStartBreadcrumb(url, headers);
    62→      tabStore.resetNavigation(activeTabId, url, stack);
    63→      break;
    64→    }
    65→  }
    66→}
    67→
    68→/**
    69→ * Breadcrumb click handler — pops to the Nth breadcrumb item.
    70→ * Deduplicates: if a matching entry already exists in backward history, jumps there.
    71→ * Otherwise inserts before current position.
    72→ */
    73→export function popToBreadcrumb(
    74→  index: number,
    75→  tabStore: {
    76→    activeTabId: string;
    77→    getCurrentState: (tabId: string) => { breadcrumbStack: BreadcrumbStackItem[]; url: string } | null;
    78→    findHistoryEntryByUrl: (tabId: string, url: string) => number;
    79→    jumpToHistory: (tabId: string, historyIndex: number) => void;
    80→    insertHistoryBeforeCurrent: (tabId: string, state: { url: string; breadcrumbStack: BreadcrumbStackItem[] }) => void;
    81→  },
    82→): void {
    83→  const { activeTabId } = tabStore;
    84→  const current = tabStore.getCurrentState(activeTabId);
    85→  if (!current) return;
    86→
    87→  const targetItem = current.breadcrumbStack[index];
    88→  if (!targetItem?.href) return;
    89→
    90→  // Dedup: check if backward history already has this URL
    91→  const existingIndex = tabStore.findHistoryEntryByUrl(activeTabId, targetItem.href);
    92→  if (existingIndex >= 0) {
    93→    tabStore.jumpToHistory(activeTabId, existingIndex);
    94→    return;
    95→  }
    96→
    97→  // No match → insert new state before current (preserves forward history)
    98→  tabStore.insertHistoryBeforeCurrent(activeTabId, {
    99→    url: targetItem.href,
   100→    breadcrumbStack: current.breadcrumbStack.slice(0, index + 1),
   101→  });
   102→}
   103→
   104→/**
   105→ * Check whether the current breadcrumb stack is a valid prefix of the target match.
   106→ * Used by Tab-Router Bridge for smart push vs cold-start reset decision.
   107→ */
   108→export function isStackPrefixOf(stack: BreadcrumbStackItem[], match: RouteMatch): boolean {
   109→  if (stack.length === 0) return false;
   110→  const topPattern = stack[stack.length - 1]?.pattern;
   111→  if (!topPattern) return false;
   112→  const ancestors = deriveAncestorsFromPrefix(match.pattern);
   113→  return ancestors.includes(topPattern);
   114→}
