   147→function normalizeSnapshot(snapshot: ClosedTabSnapshot): ClosedTabSnapshot {
   148→  return {
   149→    tab: normalizeTab(snapshot.tab),
   150→    originIndex: snapshot.originIndex,
   151→    closedAt: snapshot.closedAt,
   152→  };
   153→}
