   258→// ─── Persist Migration ───────────────────────────────────────────────────────
   259→
   260→interface LegacyTabNavigationState {
   261→  location: DesktopLocation;
   262→  breadcrumbStack: Array<{
   263→    id: string;
   264→    label: string;
   265→    icon?: unknown;
   266→    descriptorId?: string;
   267→    sourceNodeId?: string;
   268→    parentNodeId?: string;
   269→    target?: {
   270→      key: string;
   271→      location: DesktopLocation;
   272→      canonicalUrl: string;
   273→    };
   274→    meta?: Record<string, unknown>;
   275→  }>;
   276→  activeNodeId?: string;
   277→  activeIndexPath?: string[];
   278→}
   279→
   280→function migrateLegacyNavigationState(legacy: LegacyTabNavigationState): TabNavigationState | null {
   281→  // Convert location to URL
   282→  let url: string;
   283→  try {
   284→    url = locationToUrl(legacy.location);
   285→  } catch {
   286→    return null;
   287→  }
   288→
   289→  // Validate URL is known in registry
   290→  if (!registry.match(url)) {
   291→    return null;
   292→  }
   293→
   294→  // Convert breadcrumb stack items (extract href from target, use new format)
   295→  const breadcrumbStack: BreadcrumbStackItem[] = legacy.breadcrumbStack.map((item) => {
   296→    const result: BreadcrumbStackItem = {
   297→      id: item.id,
   298→      label: item.label,
   299→      icon: item.icon as BreadcrumbStackItem["icon"],
   300→      href: item.target?.canonicalUrl,
   301→      sourceNodeId: item.sourceNodeId,
   302→      parentNodeId: item.parentNodeId,
   303→      meta: item.meta as BreadcrumbStackItem["meta"],
   304→    };
   305→    return result;
   306→  });
   307→
   308→  return {
   309→    url,
   310→    breadcrumbStack,
   311→    activeNodeId: legacy.activeNodeId,
   312→    activeIndexPath: legacy.activeIndexPath,
   313→  };
   314→}
   315→
   316→function isLegacyNavigationState(value: unknown): value is LegacyTabNavigationState {
   317→  if (!value || typeof value !== "object") return false;
   318→  const candidate = value as Record<string, unknown>;
   319→  return (
   320→    candidate.location !== undefined &&
   321→    typeof candidate.location === "object" &&
   322→    candidate.location !== null &&
   323→    "kind" in (candidate.location as object) &&
   324→    Array.isArray(candidate.breadcrumbStack)
   325→  );
   326→}
   327→
   328→function migratePersistedState(persisted: Record<string, unknown>): Record<string, unknown> {
   329→  const tabs = persisted.tabs;
   330→  if (!Array.isArray(tabs)) return persisted;
   331→
   332→  const migratedTabs = tabs.map((tab: unknown) => {
   333→    if (!tab || typeof tab !== "object") return tab;
   334→    const tabObj = tab as Record<string, unknown>;
   335→    const history = tabObj.navigationHistory;
   336→    if (!Array.isArray(history)) return tab;
   337→
   338→    const migratedHistory: TabNavigationState[] = [];
   339→    for (const entry of history) {
   340→      // Already in new format
   341→      if (isNavigationState(entry)) {
   342→        migratedHistory.push(entry as TabNavigationState);
   343→        continue;
   344→      }
   345→      // Legacy format
   346→      if (isLegacyNavigationState(entry)) {
   347→        const migrated = migrateLegacyNavigationState(entry);
   348→        if (migrated) {
   349→          migratedHistory.push(migrated);
   350→        }
   351→        // If migration returns null (invalid/unrecognized URL), drop the entry
   352→        continue;
   353→      }
   354→      // Unknown format, drop
   355→    }
   356→
   357→    // Ensure at least one valid entry
   358→    const safeHistory = migratedHistory.length > 0
   359→      ? migratedHistory
   360→      : [buildStateFromUrl("/workspace")];
   361→
   362→    // Clamp historyIndex
   363→    const oldIndex = typeof tabObj.historyIndex === "number" ? tabObj.historyIndex : safeHistory.length - 1;
   364→    const historyIndex = Math.min(Math.max(oldIndex, 0), safeHistory.length - 1);
   365→
   366→    return {
   367→      ...tabObj,
   368→      navigationHistory: safeHistory,
   369→      historyIndex,
   370→    };
   371→  });
   372→
   373→  // Also migrate recentlyClosedTabs
   374→  const recentlyClosed = persisted.recentlyClosedTabs;
   375→  let migratedClosed = recentlyClosed;
   376→  if (Array.isArray(recentlyClosed)) {
   377→    migratedClosed = recentlyClosed.map((snapshot: unknown) => {
   378→      if (!snapshot || typeof snapshot !== "object") return snapshot;
   379→      const snapObj = snapshot as Record<string, unknown>;
   380→      const tab = snapObj.tab;
   381→      if (!tab || typeof tab !== "object") return snapshot;
   382→      const tabObj = tab as Record<string, unknown>;
   383→      const history = tabObj.navigationHistory;
   384→      if (!Array.isArray(history)) return snapshot;
   385→
   386→      const migratedHistory: TabNavigationState[] = [];
   387→      for (const entry of history) {
   388→        if (isNavigationState(entry)) {
   389→          migratedHistory.push(entry as TabNavigationState);
   390→          continue;
   391→        }
   392→        if (isLegacyNavigationState(entry)) {
   393→          const migrated = migrateLegacyNavigationState(entry);
   394→          if (migrated) {
   395→            migratedHistory.push(migrated);
   396→          }
   397→          continue;
   398→        }
   399→      }
   400→
   401→      const safeHistory = migratedHistory.length > 0
   402→        ? migratedHistory
   403→        : [buildStateFromUrl("/workspace")];
   404→
   405→      const oldIndex = typeof tabObj.historyIndex === "number" ? tabObj.historyIndex : safeHistory.length - 1;
   406→      const historyIndex = Math.min(Math.max(oldIndex, 0), safeHistory.length - 1);
   407→
   408→      return {
   409→        ...snapObj,
   410→        tab: {
   411→          ...tabObj,
   412→          navigationHistory: safeHistory,
   413→          historyIndex,
   414→        },
   415→      };
   416→    });
   417→  }
   418→
   419→  return {
   420→    ...persisted,
   421→    tabs: migratedTabs,
   422→    recentlyClosedTabs: migratedClosed,
   423→  };
   424→}
