      openPromptDetail,
      openCommandDetail,
      openDocuments,
      openDevicePair,
      openDashboard,
      openSkillsMarket,

      pushChildPage,
      pushCurrentPageChild,
      openCurrentPageWeb,

      openRoute,
      focusOrOpenRoute,
      openPath,
      handleDeepLink,

      canGoBack: tabState.canGoBack,
      canGoForward: tabState.canGoForward,
      goBack: tabNav.goBackInTab,
      goForward: tabNav.goForwardInTab,
      closeCurrentTab,
      detachCurrentTabToNewWindow,
      popToBreadcrumb,

      setHeaderCenter,
      setHeaderRight,
      clearHeaderSlots,
      headerCenter: null,
      headerRight: null,
    }),
    [
      clearHeaderSlots,
      closeCurrentTab,
      detachCurrentTabToNewWindow,
      currentDescriptor,
      currentUrl,
      currentStack,
      currentWorkspace,
      currentWorkspaceId,
      focusOrOpenRoute,
